def mark_missed_call_tasks(apps, schema_editor):
    """Tasks made before `source` existed: the ones linked to a call came
    from the missed-call signal, the rest were raised by staff."""
    CallbackTask = apps.get_model("telephony", "CallbackTask")
    CallbackTask.objects.filter(call__isnull=False).update(source="missed_call")


